/* Buttons */
/* Base (0-480px) - Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 1rem 2rem;
    border: none;
    border-radius: 50px;
    font-family: 'Inter', sans-serif;
    font-weight: 600;
    font-size: 14px;
    cursor: pointer;
    transition: all 0.3s ease;
    text-decoration: none;
    text-align: center;
    outline: none;
    position: relative;
    overflow: hidden;
    /* Accessible tap targets */
    min-height: 48px;
    min-width: 200px;
    width: 100%;
    max-width: 280px;
}

.btn:focus {
    outline: 2px solid var(--saffron-gold);
    outline-offset: 2px;
}

.btn span {
    z-index: 2;
    position: relative;
}

.btn span:first-child {
    margin-right: 0.5rem;
    font-size: 1.1em;
}

.btn i {
    margin-right: 0.5rem;
    z-index: 2;
    position: relative;
    font-size: 1.1em;
}

/* Mobile-first responsive buttons - padding adjustments only */
@media (min-width: 480px) {
    .btn {
        padding: 0.8rem 1.8rem;
    }
}

@media (min-width: 768px) {
    .btn {
        padding: 0.75rem 2rem;
    }
}

/* Base hover effect - will be overridden by specific button types */
.btn:hover {
    /* Base hover styles handled by specific button classes */
}

.btn-primary {
    background: linear-gradient(135deg, #f4a300 0%, #e69500 100%);
    color: var(--deep-earth-brown);
}

.btn-primary:hover {
    background: linear-gradient(135deg, #e69500 0%, #d48900 100%);
    transform: translateY(-2px) scale(1.02);
    box-shadow: 0 12px 25px rgba(244, 163, 0, 0.4);
}

.btn-secondary {
    background: rgba(255, 255, 255, 0.1);
    color: white;
    border: 2px solid white;
    backdrop-filter: blur(10px);
}

.btn-secondary:hover {
    background: rgba(255, 255, 255, 0.2);
    border-color: white;
    color: white;
    transform: translateY(-2px) scale(1.02);
    box-shadow: 0 12px 25px rgba(255, 255, 255, 0.2);
}

.btn-outline {
    background: transparent;
    color: var(--deep-earth-brown);
    border: 2px solid var(--deep-earth-brown);
}

.btn-outline:hover {
    background: var(--deep-earth-brown);
    color: white;
}

