    color: var(--deep-earth-brown);
    border: 2px solid var(--deep-earth-brown);
    padding: 0.75rem 1.5rem;
    border-radius: 25px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.3s ease;
}

.filter-btn:hover,
.filter-btn.active {
    background: var(--deep-earth-brown);
    color: white;
}

.filter-btn.active {
    background: var(--saffron-gold);
    border-color: var(--saffron-gold);
}

/* Gallery Lightbox */
.gallery-lightbox {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.9);
    z-index: 10000;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
}

.gallery-lightbox.active {
    opacity: 1;
    visibility: visible;
}

.lightbox-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    cursor: pointer;
}

.lightbox-content {
    position: relative;
    max-width: 90%;
    max-height: 90%;
    background: white;
    border-radius: 15px;
    overflow: hidden;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    display: flex;
    flex-direction: column;
    transform: scale(0.9);
    transition: transform 0.3s ease;
}

.gallery-lightbox.active .lightbox-content {
    transform: scale(1);
}

.lightbox-close {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background: rgba(0, 0, 0, 0.7);
    color: white;
    border: none;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    z-index: 10;
    transition: all 0.3s ease;
}

.lightbox-close:hover {
    background: rgba(0, 0, 0, 0.9);
}

.lightbox-image-container {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 400px;
}

.lightbox-image-container img {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
}

.lightbox-info {
    padding: 1.5rem;
    background: var(--cream);
    border-top: 1px solid rgba(0, 0, 0, 0.1);
}

.lightbox-info h3 {
    font-size: 1.3rem;
    color: var(--deep-earth-brown);
    margin-bottom: 0.5rem;
    font-weight: 600;
}

.lightbox-info p {
    font-size: 1rem;
    color: var(--gray-700);
    line-height: 1.5;
}

/* Animation keyframes */
@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Mobile Slideshow Styles */
@media (max-width: 768px) {
    .gallery {
        padding: 3rem 0;
    }

    .slideshow-container {
        height: 400px;
        border-radius: 15px;
    }

    .slide {
        flex-direction: column;
    }

    .slide-image {
        height: 200px;
    }

    .slide-content {
        padding: 2rem 1.5rem;
        height: 200px;
    }

    .slide-info h3 {
        font-size: 1.4rem;
        margin-bottom: 0.5rem;
    }

    .slide-info p {
        font-size: 0.9rem;
        margin-bottom: 1rem;
    }

    .slide-category {
        font-size: 0.8rem;
        padding: 0.4rem 0.8rem;
        margin-bottom: 1rem;
    }

    .slide-view-btn {
        padding: 0.6rem 1.5rem;
        font-size: 0.9rem;
    }

    .nav-btn {
