// TradeArk - Main JavaScript File

// Global Variables
let currentTestimonial = 0;
const testimonials = document.querySelectorAll('.testimonial-card');
const testimonialDots = document.querySelectorAll('.dot');

// reCAPTCHA Configuration
const RECAPTCHA_CONFIG = {
    siteKey: null,
    initialized: false
};

// DOM Content Loaded Event
document.addEventListener('DOMContentLoaded', function() {
    initializeNavigation();
    initializeScrollEffects();
    initializeParallax();
    initializeRecaptcha();
    initializeForms();
    initializeTestimonials();
    initializeAnimations();
    initializeScrollIndicator();
    initializeLanguageManager();
    initializeGallery();

});

// Removed forceImageRefresh - no longer needed after gallery optimization

// Language Manager Initialization
function initializeLanguageManager() {
    if (typeof LanguageManager !== 'undefined') {
        window.languageManager = new LanguageManager();
    }
}

// reCAPTCHA Initialization
function initializeRecaptcha() {
    // Check if site key is already set in HTML
    const recaptchaElements = document.querySelectorAll('.g-recaptcha');
    if (recaptchaElements.length > 0) {
        const firstElement = recaptchaElements[0];
        const siteKey = firstElement.getAttribute('data-sitekey');

        if (siteKey && siteKey !== '') {
            RECAPTCHA_CONFIG.siteKey = siteKey;
            RECAPTCHA_CONFIG.initialized = true;

            // Initialize reCAPTCHA when script loads
            if (typeof grecaptcha !== 'undefined') {
                // Script already loaded, initialize immediately
                setTimeout(initializeRecaptchaWidgets, 100);
            } else {
                // Wait for script to load
                window.addEventListener('load', () => {
                    setTimeout(initializeRecaptchaWidgets, 100);
                });
            }
        }
    }
}

// Initialize reCAPTCHA widgets
function initializeRecaptchaWidgets() {
    if (typeof grecaptcha !== 'undefined' && RECAPTCHA_CONFIG.siteKey) {
        document.querySelectorAll('.g-recaptcha').forEach((element, index) => {
            if (!element.hasAttribute('data-widget-id')) {
                try {
                    const widgetId = grecaptcha.render(element, {
                        'sitekey': RECAPTCHA_CONFIG.siteKey,
                        'theme': 'light',
                        'size': 'normal'
                    });
                    element.setAttribute('data-widget-id', widgetId);
                } catch (error) {
                    console.error('Failed to render reCAPTCHA widget:', error);
                }
            }
        });
    }
}

// reCAPTCHA Validation Helper
function validateRecaptcha(recaptchaId) {
    if (!RECAPTCHA_CONFIG.initialized) {
        throw new Error('reCAPTCHA not initialized');
    }

    const recaptchaElement = document.getElementById(recaptchaId);
    if (!recaptchaElement) {
        throw new Error('reCAPTCHA element not found');
    }

    const widgetId = recaptchaElement.getAttribute('data-widget-id');
    if (!widgetId) {
        throw new Error('reCAPTCHA widget not properly initialized');
    }

    const response = grecaptcha.getResponse(parseInt(widgetId));
    if (!response) {
        throw new Error('Please complete the reCAPTCHA verification');
    }

    return response;
}

// Reset reCAPTCHA
function resetRecaptcha(recaptchaId) {
    const recaptchaElement = document.getElementById(recaptchaId);
    if (recaptchaElement) {
        const widgetId = recaptchaElement.getAttribute('data-widget-id');
        if (widgetId && typeof grecaptcha !== 'undefined') {
            grecaptcha.reset(parseInt(widgetId));
        }
    }
}

// Navigation Functions
function initializeNavigation() {
    initializeMobileMenu();
    initializeDesktopDropdowns();

    // Navbar scroll effect
    window.addEventListener('scroll', function() {
        const nav = document.querySelector('.nav');
        if (nav) {
            if (window.scrollY > 50) {
                nav.style.background = 'rgba(255, 255, 255, 0.98)';
                nav.style.boxShadow = '0 2px 20px rgba(0, 0, 0, 0.1)';
            } else {
                nav.style.background = 'rgba(255, 255, 255, 0.95)';
                nav.style.boxShadow = 'none';
            }
        }
    });
}

// Desktop dropdown functionality
function initializeDesktopDropdowns() {
    const dropdowns = document.querySelectorAll('.nav-dropdown');

    dropdowns.forEach(dropdown => {
        const dropdownToggle = dropdown.querySelector('.dropdown-toggle');
        const dropdownMenu = dropdown.querySelector('.dropdown-menu');

        if (dropdownToggle && dropdownMenu) {
            // Show dropdown on hover for desktop
            dropdown.addEventListener('mouseenter', function() {
                if (window.innerWidth > 1023) {
                    dropdownMenu.style.display = 'block';
                }
            });

            dropdown.addEventListener('mouseleave', function() {
                if (window.innerWidth > 1023) {
                    dropdownMenu.style.display = 'none';
                }
            });
        }
    });
}



// Toggle mobile dropdown
function toggleMobileDropdown(dropdown) {
    const isActive = dropdown.classList.contains('active');

    // Close all other dropdowns
    document.querySelectorAll('.nav-dropdown').forEach(d => {
        if (d !== dropdown) {
            d.classList.remove('active');
        }
    });

    // Toggle current dropdown
    if (isActive) {
        dropdown.classList.remove('active');
    } else {
        dropdown.classList.add('active');
    }
}



// Smooth Scrolling Function
function scrollToSection(sectionId) {
    const element = document.getElementById(sectionId);
    if (element) {
        const offsetTop = element.offsetTop - 80; // Account for fixed navbar
        window.scrollTo({
            top: offsetTop,
            behavior: 'smooth'
        });
    }
}

// Initialize Scroll Indicator
function initializeScrollIndicator() {
    const scrollIndicator = document.getElementById('scroll-explore');

    if (scrollIndicator) {
        // Add click event listener as backup
        scrollIndicator.addEventListener('click', function(e) {
            e.preventDefault();
            scrollToSection('about');
        });

        // Add keyboard accessibility
        scrollIndicator.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                scrollToSection('about');
            }
        });

        // Add focus styles for accessibility
        scrollIndicator.setAttribute('tabindex', '0');
        scrollIndicator.setAttribute('role', 'button');
        scrollIndicator.setAttribute('aria-label', 'Scroll to About section');
    }
}

// Enhanced Parallax Effect
function initializeParallax() {
    const parallaxBg = document.querySelector('.hero-bg');

    if (parallaxBg) {
        // Throttle scroll events for better performance
        let ticking = false;

        function updateParallax() {
            const scrolled = window.pageYOffset;
            const rate = scrolled * 0.3; // Changed to positive for downward movement
            const scale = 1 + (scrolled * 0.0001);
            parallaxBg.style.transform = `translateY(${rate}px) scale(${scale})`;
            ticking = false;
        }

        window.addEventListener('scroll', function() {
            if (!ticking) {
                requestAnimationFrame(updateParallax);
                ticking = true;
            }
        });
    }
}

// Scroll Effects and Animations
function initializeScrollEffects() {
    const observerOptions = {
        threshold: 0.1,
        rootMargin: '0px 0px -20px 0px'
    };

    const observer = new IntersectionObserver(function(entries) {
        entries.forEach(entry => {
            if (entry.isIntersecting && !entry.target.classList.contains('animate-fade-in')) {
                // Reduced delay for contact section
                const delay = entry.target.closest('.contact') ? 50 : 200;
                setTimeout(() => {
                    entry.target.classList.add('animate-fade-in');
                }, delay);
                observer.unobserve(entry.target); // Stop observing after animation
            }
        });
    }, observerOptions);

    // Observe all sections and cards
    const elementsToAnimate = document.querySelectorAll(
        '.section-header, .product-card, .why-us-card, .pillar, .cert-item, .quality-stats, .testimonial-card'
    );

    elementsToAnimate.forEach(element => {
        observer.observe(element);
    });
}

// Form Handling
function initializeForms() {
    const contactForm = document.getElementById('contactForm');
    const newsletterForm = document.getElementById('newsletterForm');
    const productInterestSelect = document.getElementById('productInterest');
    const customSourcingField = document.getElementById('customSourcingField');

    // Contact Form - Handle Web3Forms submission
    if (contactForm) {
        contactForm.addEventListener('submit', function(e) {
            e.preventDefault();
            handleContactForm(this);
        });
    }

    // Newsletter Form
    if (newsletterForm) {
        newsletterForm.addEventListener('submit', function(e) {
            e.preventDefault();
            handleNewsletterForm(this);
        });
    }

    // Product Interest Dropdown - Show/Hide Custom Sourcing Field
    if (productInterestSelect && customSourcingField) {
        productInterestSelect.addEventListener('change', function() {
            const selectedValue = this.value;
            const customSourcingInput = document.getElementById('customSourcingDetails');

            if (selectedValue === 'custom-sourcing') {
                // Show the custom sourcing field with smooth animation
                customSourcingField.style.display = 'block';
                customSourcingField.style.opacity = '0';
                customSourcingField.style.transform = 'translateY(-10px)';

                // Animate in
                setTimeout(() => {
                    customSourcingField.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
                    customSourcingField.style.opacity = '1';
                    customSourcingField.style.transform = 'translateY(0)';
                }, 10);

                // Focus on the input field
                setTimeout(() => {
                    if (customSourcingInput) {
                        customSourcingInput.focus();
                    }
                }, 300);
            } else {
                // Hide the custom sourcing field with smooth animation
                customSourcingField.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
                customSourcingField.style.opacity = '0';
                customSourcingField.style.transform = 'translateY(-10px)';

                // Clear the input value
                if (customSourcingInput) {
                    customSourcingInput.value = '';
                }

                // Hide completely after animation
                setTimeout(() => {
                    customSourcingField.style.display = 'none';
                }, 300);
            }
        });
    }
}

// Handle Contact Form Submission
function handleContactForm(form) {
    const submitButton = form.querySelector('.form-submit');
    const originalText = submitButton.textContent;

    // Prevent double submission
    if (submitButton.dataset.submitting === 'true') {
        return;
    }

    // Validate reCAPTCHA first
    try {
        const recaptchaResponse = validateRecaptcha('contactRecaptcha');
        // reCAPTCHA validation successful
    } catch (error) {
        showNotification(error.message, 'error');
        return;
    }

    // Mark as submitting
    submitButton.dataset.submitting = 'true';

    // Show loading state with spinner
    submitButton.innerHTML = '<span class="btn-spinner"></span> Sending...';
    submitButton.disabled = true;
    submitButton.classList.add('btn-loading');

    // Convert form data to JSON as required by Web3Forms
    const formData = new FormData(form);
    const object = Object.fromEntries(formData);

    // Add reCAPTCHA response
    try {
        const recaptchaResponse = validateRecaptcha('contactRecaptcha');
        object['g-recaptcha-response'] = recaptchaResponse;
    } catch (error) {
        // This shouldn't happen since we already validated, but handle gracefully
        // reCAPTCHA validation failed
    }

    const json = JSON.stringify(object);

    // Submit to Web3Forms API with proper headers and timeout
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 second timeout

    fetch('https://api.web3forms.com/submit', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        },
        body: json,
        signal: controller.signal
    })
    .then(async (response) => {
        let responseData = await response.json();
        if (response.status == 200) {
            // Success - reset form and show success message
            form.reset();
            // Reset reCAPTCHA
            resetRecaptcha('contactRecaptcha');
            // Also hide the custom sourcing field after form reset
            const customSourcingField = document.getElementById('customSourcingField');
            if (customSourcingField) {
                customSourcingField.style.display = 'none';
            }
            showNotification('Thank you! Your message has been sent successfully. We will get back to you soon.', 'success');
        } else {
            // Error - show error message and reset reCAPTCHA
            resetRecaptcha('contactRecaptcha');
            showNotification(responseData.message || 'Sorry, there was an error sending your message. Please try again or contact us directly.', 'error');
        }
    })
    .catch(error => {
        clearTimeout(timeoutId);
        // Reset reCAPTCHA on error
        resetRecaptcha('contactRecaptcha');
        // Handle network error
        if (error.name === 'AbortError') {
            showNotification('Request timed out. Please check your connection and try again.', 'error');
        } else {
            showNotification('Network error: Unable to send message. Please check your connection and try again.', 'error');
        }
    })
    .finally(() => {
        clearTimeout(timeoutId);
        // Reset button state
        submitButton.innerHTML = originalText;
        submitButton.disabled = false;
        submitButton.classList.remove('btn-loading');
        // Reset submission flag
        submitButton.dataset.submitting = 'false';
    });
}

// Handle Newsletter Form Submission
function handleNewsletterForm(form) {
    const formData = new FormData(form);
    const submitButton = form.querySelector('button[type="submit"]');
    const originalText = submitButton.textContent;

    // Show loading state
    submitButton.textContent = 'Subscribing...';
    submitButton.disabled = true;

    // Prepare data for Web3Forms
    const data = {
        access_key: '74f025aa-6671-48aa-9181-7922d4e71f7c',
        email: formData.get('email'),
        subject: 'Newsletter Subscription from TradeArk Website',
        from_name: 'TradeArk Newsletter Form',
        action: 'newsletter_subscription'
    };

    // Submit to Web3Forms API
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 second timeout

    fetch('https://api.web3forms.com/submit', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        },
        body: JSON.stringify(data),
        signal: controller.signal
    })
    .then(async (response) => {
        let responseData = await response.json();
        if (response.status == 200) {
            // Success - show success message and reset form
            showNotification('Successfully subscribed to our newsletter!', 'success');
            form.reset();
        } else {
            // Error - show error message
            showNotification(responseData.message || 'Sorry, there was an error subscribing. Please try again.', 'error');
        }
    })
    .catch(error => {
        clearTimeout(timeoutId);
        // Handle network error
        if (error.name === 'AbortError') {
            showNotification('Request timed out. Please check your connection and try again.', 'error');
        } else {
            showNotification('Network error: Unable to subscribe. Please check your connection and try again.', 'error');
        }
    })
    .finally(() => {
        clearTimeout(timeoutId);
        // Reset button state
        submitButton.textContent = originalText;
        submitButton.disabled = false;
    });
}

// Testimonials Carousel
function initializeTestimonials() {
    showTestimonial(0);

    // Auto-rotate testimonials
    setInterval(() => {
        changeTestimonial(1);
    }, 5000);
}

function showTestimonial(index) {
    // Hide all testimonials
    testimonials.forEach(testimonial => {
        testimonial.classList.remove('active');
    });

    // Remove active class from all dots
    testimonialDots.forEach(dot => {
        dot.classList.remove('active');
    });

    // Show current testimonial
    if (testimonials[index]) {
        testimonials[index].classList.add('active');
    }

    // Update active dot
    if (testimonialDots[index]) {
        testimonialDots[index].classList.add('active');
    }

    currentTestimonial = index;
}

function changeTestimonial(direction) {
    let newIndex = currentTestimonial + direction;

    if (newIndex >= testimonials.length) {
        newIndex = 0;
    } else if (newIndex < 0) {
        newIndex = testimonials.length - 1;
    }

    showTestimonial(newIndex);
}

function goToTestimonial(index) {
    showTestimonial(index);
}

// Initialize Animations
function initializeAnimations() {
    const observerOptions = {
        threshold: 0.1,
        rootMargin: '0px 0px -50px 0px'
    };

    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting && !entry.target.classList.contains('visible')) {
                setTimeout(() => {
                    entry.target.classList.add('visible');
                }, entry.target.dataset.delay || 0);
            }
        });
    }, observerOptions);

    // Add animation classes to elements
    document.querySelectorAll('.section-header').forEach((el, index) => {
        el.classList.add('fade-in');
        el.dataset.delay = index * 100;
        observer.observe(el);
    });

    document.querySelectorAll('.product-card').forEach((el, index) => {
        el.classList.add('scale-in');
        el.dataset.delay = index * 200;
        observer.observe(el);
    });

    document.querySelectorAll('.why-us-card').forEach((el, index) => {
        el.classList.add('fade-in');
        el.dataset.delay = index * 150;
        observer.observe(el);
    });

    document.querySelectorAll('.pillar').forEach((el, index) => {
        el.classList.add('slide-left');
        el.dataset.delay = index * 100;
        observer.observe(el);
    });

    document.querySelectorAll('.cert-item').forEach((el, index) => {
        el.classList.add('slide-right');
        el.dataset.delay = index * 100;
        observer.observe(el);
    });

    // Initialize number counting animation for stats
    const stats = document.querySelectorAll('.stat-number');
    const statsObserver = new IntersectionObserver(function(entries) {
        entries.forEach(entry => {
            if (entry.isIntersecting && !entry.target.dataset.animated) {
                entry.target.dataset.animated = 'true';
                animateNumber(entry.target);
                statsObserver.unobserve(entry.target); // Stop observing after animation
            }
        });
    });

    stats.forEach(stat => {
        statsObserver.observe(stat);
    });
}

// Animate Numbers
function animateNumber(element) {
    const finalNumber = element.textContent;
    const isPercentage = finalNumber.includes('%');
    const isPlus = finalNumber.includes('+');
    const numericValue = parseFloat(finalNumber.replace(/[^\d.]/g, ''));

    let currentNumber = 0;
    const increment = numericValue / 50;

    const timer = setInterval(() => {
        currentNumber += increment;

        if (currentNumber >= numericValue) {
            currentNumber = numericValue;
            clearInterval(timer);
        }

        let displayValue = currentNumber.toString();
        // Handle decimal formatting for percentages
        if (isPercentage && numericValue % 1 !== 0) {
            displayValue = currentNumber.toFixed(1);
        } else {
            displayValue = Math.round(currentNumber).toString();
        }

        if (isPercentage) displayValue += '%';
        if (isPlus) displayValue += '+';

        element.textContent = displayValue;
    }, 30);
}

// Notification System
function showNotification(message, type = 'info') {
    // Create notification element
    const notification = document.createElement('div');
    notification.className = `notification notification-${type}`;
    notification.innerHTML = `
        <div class="notification-content">
            <span class="notification-message">${message}</span>
            <button class="notification-close" onclick="closeNotification(this)">×</button>
        </div>
    `;

    // Add styles for notification
    notification.style.cssText = `
        position: fixed;
        top: 100px;
        right: 20px;
        z-index: 10000;
        background: ${type === 'success' ? '#10b981' : '#3b82f6'};
        color: white;
        padding: 1rem 1.5rem;
        border-radius: 10px;
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
        transform: translateX(100%);
        transition: transform 0.3s ease;
        max-width: 400px;
        font-family: 'Poppins', sans-serif;
    `;

    // Add notification to body
    document.body.appendChild(notification);

    // Animate in
    setTimeout(() => {
        notification.style.transform = 'translateX(0)';
    }, 100);

    // Auto remove after 5 seconds
    setTimeout(() => {
        closeNotification(notification.querySelector('.notification-close'));
    }, 5000);
}

function closeNotification(button) {
    const notification = button.closest('.notification');
    if (notification) {
        notification.style.transform = 'translateX(100%)';
        setTimeout(() => {
            notification.remove();
        }, 300);
    }
}

// Utility Functions
function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
        const later = () => {
            clearTimeout(timeout);
            func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
    };
}

// Performance Optimizations
const debouncedScroll = debounce(function() {
    // Scroll optimizations can be added here
}, 16);

window.addEventListener('scroll', debouncedScroll);

// Lazy Loading for Images
function initializeLazyLoading() {
    const images = document.querySelectorAll('img[loading="lazy"]');

    if ('IntersectionObserver' in window) {
        const imageObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const img = entry.target;
                    img.src = img.dataset.src || img.src;
                    img.classList.remove('lazy');
                    imageObserver.unobserve(img);
                }
            });
        });

        images.forEach(img => {
            imageObserver.observe(img);
        });
    }
}

// Initialize lazy loading when DOM is ready
document.addEventListener('DOMContentLoaded', initializeLazyLoading);

// Add smooth scrolling for all internal links
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
            const offsetTop = target.offsetTop - 80;
            window.scrollTo({
                top: offsetTop,
                behavior: 'smooth'
            });
        }
    });
});

// Add loading states for buttons
document.querySelectorAll('.btn').forEach(button => {
    button.addEventListener('click', function() {
        if (this.type === 'submit') {
            return; // Form submission handled separately
        }

        // Add loading state for other buttons
        const originalText = this.textContent;
        this.textContent = 'Loading...';
        this.disabled = true;

        setTimeout(() => {
            this.textContent = originalText;
            this.disabled = false;
        }, 1000);
    });
});

// Add hover effects for cards
document.querySelectorAll('.product-card, .why-us-card, .cert-item').forEach(card => {
    card.addEventListener('mouseenter', function() {
        this.style.transform = 'translateY(-10px)';
    });

    card.addEventListener('mouseleave', function() {
        this.style.transform = 'translateY(0)';
    });
});

// Add focus management for accessibility
document.addEventListener('keydown', function(e) {
    if (e.key === 'Tab') {
        document.body.classList.add('keyboard-navigation');
    }
});

document.addEventListener('mousedown', function() {
    document.body.classList.remove('keyboard-navigation');
});

// Add CSS for keyboard navigation
const style = document.createElement('style');
style.textContent = `
    .keyboard-navigation *:focus {
        outline: 2px solid var(--saffron-gold) !important;
        outline-offset: 2px !important;
    }

    .notification-content {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
    }

    .notification-close {
        background: none;
        border: none;
        color: white;
        font-size: 1.5rem;
        cursor: pointer;
        padding: 0;
        width: 24px;
        height: 24px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 50%;
        transition: background 0.3s ease;
    }

    .notification-close:hover {
        background: rgba(255, 255, 255, 0.2);
    }

    /* New smooth animations */
    .fade-in {
        opacity: 0;
        transform: translateY(20px);
        transition: all 0.8s ease-out;
    }

    .fade-in.visible {
        opacity: 1;
        transform: translateY(0);
    }

    .slide-left {
        opacity: 0;
        transform: translateX(-30px);
        transition: all 0.8s ease-out;
    }

    .slide-left.visible {
        opacity: 1;
        transform: translateX(0);
    }

    .slide-right {
        opacity: 0;
        transform: translateX(30px);
        transition: all 0.8s ease-out;
    }

    .slide-right.visible {
        opacity: 1;
        transform: translateX(0);
    }

    .scale-in {
        opacity: 0;
        transform: scale(0.9);
        transition: all 0.8s ease-out;
    }

    .scale-in.visible {
        opacity: 1;
        transform: scale(1);
    }
`;
document.head.appendChild(style);

// Download Modal Functions
function showDownloadModal() {
    const modal = document.getElementById('downloadModal');
    if (modal) {
        modal.style.display = 'flex';
        setTimeout(() => {
            modal.classList.add('active');
        }, 10);
    }
}

function closeDownloadModal() {
    const modal = document.getElementById('downloadModal');
    if (modal) {
        modal.classList.remove('active');
        setTimeout(() => {
            modal.style.display = 'none';
            // Reset form
            const form = document.getElementById('downloadForm');
            if (form) {
                form.reset();
            }
        }, 300);
    }
}

// Initialize Download Form
function initializeDownloadForm() {
    const downloadForm = document.getElementById('downloadForm');
    const modal = document.getElementById('downloadModal');

    if (downloadForm) {
        downloadForm.addEventListener('submit', function(e) {
            e.preventDefault();
            handleDownloadForm(this);
        });
    }

    // Close modal when clicking outside
    if (modal) {
        modal.addEventListener('click', function(e) {
            if (e.target === modal) {
                closeDownloadModal();
            }
        });
    }

    // Close modal with Escape key
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            closeDownloadModal();
        }
    });
}

// Handle Download Form Submission
function handleDownloadForm(form) {
    const submitButton = form.querySelector('.download-submit');
    const originalText = submitButton.innerHTML;

    // Validate reCAPTCHA first
    try {
        const recaptchaResponse = validateRecaptcha('downloadRecaptcha');
        // Download form validation successful
    } catch (error) {
        showNotification(error.message, 'error');
        return;
    }

    // Show loading state
    submitButton.innerHTML = '<i data-lucide="loader-2"></i> Processing...';
    submitButton.disabled = true;

    // Get form data and prepare for Web3Forms
    const formData = new FormData(form);
    const currentPath = window.location.pathname;
    const catalogType = currentPath.includes('/makhana') ? 'Makhana' : 'HoReCa Cork Décor';

    const data = {
        access_key: '74f025aa-6671-48aa-9181-7922d4e71f7c',
        name: formData.get('name'),
        company: formData.get('company'),
        phone: formData.get('phone'),
        email: formData.get('email'),
        message: formData.get('message') || '',
        subject: `Download Request - ${catalogType} Catalogue from TradeArk Website`,
        from_name: 'TradeArk Download Form',
        action: 'download_catalogue'
    };

    // Add reCAPTCHA response
    try {
        const recaptchaResponse = validateRecaptcha('downloadRecaptcha');
        data['g-recaptcha-response'] = recaptchaResponse;
    } catch (error) {
        // reCAPTCHA validation failed for download
    }

    // Submit to Web3Forms API
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 second timeout

    fetch('https://api.web3forms.com/submit', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        },
        body: JSON.stringify(data),
        signal: controller.signal
    })
    .then(async (response) => {
        let responseData = await response.json();
        if (response.status == 200) {
            // Success - show notification and start download
            showNotification('Thank you! Your download will start shortly.', 'success');

            // Close modal
            closeDownloadModal();

            // Start the actual download
            const catalogType = currentPath.includes('/makhana') ? 'makhana' : 'horeca';
            triggerCatalogueDownload(catalogType);

            // Reset form and reCAPTCHA
            form.reset();
            resetRecaptcha('downloadRecaptcha');
        } else {
            // Error - show error message and reset reCAPTCHA
            resetRecaptcha('downloadRecaptcha');
            showNotification(responseData.message || 'Sorry, there was an error processing your request. Please try again.', 'error');
        }
    })
    .catch(error => {
        clearTimeout(timeoutId);
        // Reset reCAPTCHA on error
        resetRecaptcha('downloadRecaptcha');
        // Handle network error
        if (error.name === 'AbortError') {
            showNotification('Request timed out. Please check your connection and try again.', 'error');
        } else {
            showNotification('Network error: Unable to process request. Please check your connection and try again.', 'error');
        }
    })
    .finally(() => {
        clearTimeout(timeoutId);
        // Reset button state
        submitButton.innerHTML = originalText;
        submitButton.disabled = false;
    });
}

// Global function to trigger catalogue download (used by product pages)
function triggerCatalogueDownload(catalogueType = 'horeca') {
    let fileName;
    let filePath;

    // Determine the correct path based on current location
    const currentPath = window.location.pathname;
    const isInProductsFolder = currentPath.includes('/products/');
    const basePath = isInProductsFolder ? '../' : './';

    if (catalogueType === 'horeca') {
        fileName = 'The Cork Studio HoReCa Catalogue.pdf';
        filePath = basePath + 'Downloadables/The Cork Studio HoReCa Catalogue.pdf';
    } else {
        fileName = 'TradeArk Makhana Brochure.pdf';
        filePath = basePath + 'Downloadables/TradeArk Makhana Brochure.pdf';
    }

    // Create a link element to trigger download
    const link = document.createElement('a');
    link.href = filePath;
    link.download = fileName;
    link.target = '_blank';

    // Append to body, click, and remove
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}

// Export functions for global use
window.scrollToSection = scrollToSection;
window.changeTestimonial = changeTestimonial;
window.goToTestimonial = goToTestimonial;
window.closeNotification = closeNotification;
window.showDownloadModal = showDownloadModal;
window.closeDownloadModal = closeDownloadModal;
window.triggerCatalogueDownload = triggerCatalogueDownload;
window.initializeDownloadForm = initializeDownloadForm;

// ===== NEW MOBILE MENU SYSTEM =====

function initializeMobileMenu() {
    const mobileMenuToggle = document.querySelector('.mobile-menu-toggle');
    const mobileMenuOverlay = document.querySelector('.mobile-menu-overlay');
    const mobileMenuClose = document.querySelector('.mobile-menu-close');
    const mobileMenuLinks = document.querySelectorAll('.mobile-menu-link:not(.mobile-menu-toggle-btn)');
    const mobileMenuSublinks = document.querySelectorAll('.mobile-menu-sublink');
    const mobileMenuToggleBtns = document.querySelectorAll('.mobile-menu-toggle-btn');

    // Ensure Lucide icons are properly rendered in mobile menu
    if (typeof lucide !== 'undefined' && lucide.createIcons) {
        lucide.createIcons();
    }



    // Toggle mobile menu
    if (mobileMenuToggle) {
        mobileMenuToggle.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            toggleMobileMenu();
        });
    }

    // Close mobile menu
    if (mobileMenuClose) {
        mobileMenuClose.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            closeMobileMenu();
        });
    }

    // Close menu when clicking overlay
    if (mobileMenuOverlay) {
        mobileMenuOverlay.addEventListener('click', function(e) {
            if (e.target === mobileMenuOverlay) {
                closeMobileMenu();
            }
        });
    }

    // Close menu when clicking direct links and handle smooth scrolling
    mobileMenuLinks.forEach(link => {
        link.addEventListener('click', function(e) {
            const href = this.getAttribute('href');

            // Handle internal anchor links
            if (href && href.startsWith('#')) {
                e.preventDefault();
                const sectionId = href.substring(1);
                scrollToSection(sectionId);
                closeMobileMenu();
            } else {
                // For external links, just close the menu
                closeMobileMenu();
            }
        });
    });

    // Close menu when clicking sub-links
    mobileMenuSublinks.forEach(sublink => {
        sublink.addEventListener('click', function() {
            closeMobileMenu();
        });
    });

    // Handle expandable menu items
    mobileMenuToggleBtns.forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            toggleMobileSubmenu(btn);
        });

        // Keyboard support
        btn.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                toggleMobileSubmenu(btn);
            }
        });
    });

    // Close menu with Escape key
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && mobileMenuOverlay && mobileMenuOverlay.classList.contains('active')) {
            closeMobileMenu();
        }
    });

    // Handle swipe gestures for closing menu
    let touchStartX = 0;
    let touchEndX = 0;

    if (mobileMenuOverlay) {
        mobileMenuOverlay.addEventListener('touchstart', function(e) {
            touchStartX = e.changedTouches[0].screenX;
        });

        mobileMenuOverlay.addEventListener('touchend', function(e) {
            touchEndX = e.changedTouches[0].screenX;
            handleSwipeGesture();
        });
    }

    function handleSwipeGesture() {
        const swipeThreshold = 50;
        const swipeDistance = touchEndX - touchStartX;

        // Swipe left to close menu
        if (swipeDistance < -swipeThreshold) {
            closeMobileMenu();
        }
    }
}

function toggleMobileMenu() {
    const mobileMenuToggle = document.querySelector('.mobile-menu-toggle');
    const mobileMenuOverlay = document.querySelector('.mobile-menu-overlay');
    const body = document.body;

    if (mobileMenuOverlay && mobileMenuToggle) {
        const isOpen = mobileMenuOverlay.classList.contains('active');

        if (isOpen) {
            closeMobileMenu();
        } else {
            openMobileMenu();
        }
    }
}

function openMobileMenu() {
    const mobileMenuToggle = document.querySelector('.mobile-menu-toggle');
    const mobileMenuOverlay = document.querySelector('.mobile-menu-overlay');
    const body = document.body;

    if (mobileMenuOverlay && mobileMenuToggle) {
        mobileMenuOverlay.classList.add('active');
        mobileMenuToggle.classList.add('active');
        body.classList.add('mobile-menu-open');

        // Re-initialize Lucide icons when menu opens to ensure chevrons are visible
        if (typeof lucide !== 'undefined' && lucide.createIcons) {
            setTimeout(() => {
                lucide.createIcons();
            }, 100);
        }

        // Focus the close button for accessibility
        setTimeout(() => {
            const closeBtn = document.querySelector('.mobile-menu-close');
            if (closeBtn) {
                closeBtn.focus();
            }
        }, 300);
    }
}

function closeMobileMenu() {
    const mobileMenuToggle = document.querySelector('.mobile-menu-toggle');
    const mobileMenuOverlay = document.querySelector('.mobile-menu-overlay');
    const body = document.body;

    if (mobileMenuOverlay && mobileMenuToggle) {
        mobileMenuOverlay.classList.remove('active');
        mobileMenuToggle.classList.remove('active');
        body.classList.remove('mobile-menu-open');

        // Close all open submenus
        const expandedItems = document.querySelectorAll('.mobile-menu-expandable.expanded');
        expandedItems.forEach(item => {
            item.classList.remove('expanded');
            const toggleBtn = item.querySelector('.mobile-menu-toggle-btn');
            if (toggleBtn) {
                toggleBtn.setAttribute('aria-expanded', 'false');
            }
        });
    }
}

function toggleMobileSubmenu(toggleBtn) {
    const parentItem = toggleBtn.closest('.mobile-menu-expandable');
    const isExpanded = parentItem.classList.contains('expanded');

    // Close all other open submenus (only one open at a time)
    const allExpandedItems = document.querySelectorAll('.mobile-menu-expandable.expanded');
    allExpandedItems.forEach(item => {
        if (item !== parentItem) {
            item.classList.remove('expanded');
            const otherToggleBtn = item.querySelector('.mobile-menu-toggle-btn');
            if (otherToggleBtn) {
                otherToggleBtn.setAttribute('aria-expanded', 'false');
            }
        }
    });

    // Toggle current submenu
    if (isExpanded) {
        parentItem.classList.remove('expanded');
        toggleBtn.setAttribute('aria-expanded', 'false');
    } else {
        parentItem.classList.add('expanded');
        toggleBtn.setAttribute('aria-expanded', 'true');
    }
}

// Gallery Slideshow Functions
let currentSlide = 0;
let slideInterval;
let slides = [];
let allSlides = [];

function initializeGallery() {
    const filterButtons = document.querySelectorAll('.filter-btn');
    allSlides = document.querySelectorAll('.slide');
    slides = Array.from(allSlides);

    // Initialize filter functionality only if filter buttons exist
    if (filterButtons.length > 0) {
        filterButtons.forEach(button => {
            button.addEventListener('click', function() {
                const filter = this.dataset.filter;

                // Update active button
                filterButtons.forEach(btn => btn.classList.remove('active'));
                this.classList.add('active');

                // Filter slides
                filterSlides(filter);
            });
        });
    }

    // Initialize slideshow functionality
    initializeSlideshow();

    // Initialize lightbox functionality
    initializeLightbox();
}

function filterSlides(filter) {
    // Reset slideshow
    clearInterval(slideInterval);
    currentSlide = 0;

    // Filter slides based on category
    if (filter === 'all') {
        slides = Array.from(allSlides);
    } else {
        slides = Array.from(allSlides).filter(slide => slide.dataset.category === filter);
    }

    // Hide all slides
    allSlides.forEach(slide => {
        slide.classList.remove('active');
        slide.style.display = 'none';
    });

    // Show filtered slides
    slides.forEach(slide => {
        slide.style.display = 'flex';
    });

    // Update dots
    updateDots();

    // Show first slide if any exist
    if (slides.length > 0) {
        slides[0].classList.add('active');
        startSlideshow();
    }
}

function initializeSlideshow() {
    // Show first slide
    if (slides.length > 0) {
        slides[0].classList.add('active');
    }

    // Start auto-advance
    startSlideshow();

    // Pause on hover
    const slideshow = document.querySelector('.slideshow-container');
    if (slideshow) {
        slideshow.addEventListener('mouseenter', () => {
            clearInterval(slideInterval);
        });

        slideshow.addEventListener('mouseleave', () => {
            startSlideshow();
        });
    }

    // Keyboard navigation
    document.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowLeft') {
            changeSlide(-1);
        } else if (e.key === 'ArrowRight') {
            changeSlide(1);
        }
    });
}

function startSlideshow() {
    clearInterval(slideInterval);
    if (slides.length > 1) {
        slideInterval = setInterval(() => {
            changeSlide(1);
        }, 5000); // Change slide every 5 seconds
    }
}

function changeSlide(direction) {
    if (slides.length === 0) return;

    // Remove active class from current slide
    slides[currentSlide].classList.remove('active');

    // Calculate next slide
    currentSlide += direction;

    if (currentSlide >= slides.length) {
        currentSlide = 0;
    } else if (currentSlide < 0) {
        currentSlide = slides.length - 1;
    }

    // Add active class to new slide
    slides[currentSlide].classList.add('active');

    // Update dots
    updateDots();

    // Update progress bar
    updateProgressBar();
}

function goToSlide(index) {
    if (slides.length === 0 || index >= slides.length) return;

    // Remove active class from current slide
    slides[currentSlide].classList.remove('active');

    // Set new current slide
    currentSlide = index;

    // Add active class to new slide
    slides[currentSlide].classList.add('active');

    // Update dots
    updateDots();

    // Update progress bar
    updateProgressBar();

    // Restart slideshow
    startSlideshow();
}

function updateDots() {
    const dots = document.querySelectorAll('.slideshow-dots .dot');
    dots.forEach((dot, index) => {
        if (index < slides.length) {
            dot.style.display = 'block';
            dot.classList.toggle('active', index === currentSlide);
        } else {
            dot.style.display = 'none';
        }
    });
}

function updateProgressBar() {
    const progressBar = document.querySelector('.progress-bar');
    if (progressBar && slides.length > 0) {
        const progress = ((currentSlide + 1) / slides.length) * 100;
        progressBar.style.width = progress + '%';
    }
}

function initializeLightbox() {
    const lightbox = document.getElementById('galleryLightbox');

    // Close lightbox when clicking outside
    if (lightbox) {
        lightbox.addEventListener('click', function(e) {
            if (e.target === lightbox || e.target.classList.contains('lightbox-overlay')) {
                closeLightbox();
            }
        });

        // Close lightbox with Escape key
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape' && lightbox.classList.contains('active')) {
                closeLightbox();
            }
        });
    }
}

function openLightbox(imageSrc, title, description) {
    const lightbox = document.getElementById('galleryLightbox');
    const lightboxImage = document.getElementById('lightboxImage');
    const lightboxTitle = document.getElementById('lightboxTitle');
    const lightboxDescription = document.getElementById('lightboxDescription');

    if (lightbox && lightboxImage && lightboxTitle && lightboxDescription) {
        lightboxImage.src = imageSrc;
        lightboxImage.alt = title;
        lightboxTitle.textContent = title;
        lightboxDescription.textContent = description;

        lightbox.style.display = 'flex';
        setTimeout(() => {
            lightbox.classList.add('active');
        }, 10);

        // Prevent body scrolling
        document.body.style.overflow = 'hidden';
    }
}

function closeLightbox() {
    const lightbox = document.getElementById('galleryLightbox');

    if (lightbox) {
        lightbox.classList.remove('active');
        setTimeout(() => {
            lightbox.style.display = 'none';
        }, 300);

        // Restore body scrolling
        document.body.style.overflow = '';
    }
}

tradeark-html/assets/css/style.css.content:
/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    /* TradeArk Brand Colors */
    --deep-earth-brown: #5B3A29;
    --saffron-gold: #F4A300;
    --cream: #FFF8EC;
    --slate-gray: #ECE7E1;
    --warm-terracotta: #D2691E;

    /* Hero Section Colors */
    --hero-cream: hsl(35, 25%, 92%);
    --hero-beige: hsl(30, 20%, 85%);
    --hero-charcoal: hsl(210, 10%, 15%);
    --hero-wood: hsl(25, 35%, 40%);
    --hero-linen: hsl(40, 30%, 88%);

    /* Additional Colors */
    --white: #ffffff;
    --black: #000000;
    --gray-100: #f7fafc;
    --gray-200: #edf2f7;
    --gray-300: #e2e8f0;
    --gray-400: #cbd5e0;
    --gray-500: #a0aec0;
    --gray-600: #718096;
    --gray-700: #4a5568;
    --gray-800: #2d3748;
    --gray-900: #1a202c;
}

body {
    font-family: 'Inter', sans-serif;
    line-height: 1.6;
    color: var(--gray-800);
    background-color: var(--white);
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

/* Typography */
.font-montserrat { font-family: 'Montserrat', sans-serif; }
.font-lora { font-family: 'Lora', serif; }
.font-poppins { font-family: 'Poppins', sans-serif; }

/* Navigation */
.nav {
    position: fixed;
    top: 0;
    width: 100%;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(10px);
    z-index: 1000;
    transition: all 0.3s ease;
}

.nav-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 2rem;
    max-width: 1200px;
    margin: 0 auto;
}

.nav-logo {
    font-family: 'Montserrat', sans-serif;
    font-size: 1.8rem;
    font-weight: 700;
    color: var(--deep-earth-brown);
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav-link {
    text-decoration: none;
    color: var(--deep-earth-brown);
    font-weight: 500;
    transition: color 0.3s ease;
}

.nav-link:hover {
    color: var(--saffron-gold);
}

.nav-toggle {
    display: none;
    flex-direction: column;
    cursor: pointer;
}

.nav-toggle span {
    width: 25px;
    height: 3px;
    background: var(--deep-earth-brown);
    margin: 3px 0;
    transition: 0.3s;
}

/* Hero Section */
.hero {
    position: relative;
    height: 100vh;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
}

.hero-bg {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 120%;
    background: linear-gradient(135deg, var(--hero-wood) 0%, var(--hero-charcoal) 100%);
    background-size: cover;
    background-position: center;
    will-change: transform;
    transition: transform 0.1s ease-out;
}

.hero-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, rgba(0,0,0,0.6) 0%, rgba(0,0,0,0.4) 50%, rgba(0,0,0,0.6) 100%);
    z-index: 1;
}

.hero-content {
    position: relative;
    z-index: 2;
    text-align: center;
    color: white;
    width: 100%;
}

.hero-inner {
    max-width: 800px;
    margin: 0 auto;
    padding: 0 20px;
}

.hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    background: rgba(244, 163, 0, 0.2);
    border: 1px solid rgba(244, 163, 0, 0.3);
    border-radius: 50px;
    padding: 0.5rem 1.5rem;
    margin-bottom: 2rem;
    color: var(--saffron-gold);
    font-family: 'Montserrat', sans-serif;
    font-weight: 500;
    backdrop-filter: blur(10px);
    animation: fadeIn 0.6s ease-in-out 0.1s both;
}

.hero-title {
    font-family: 'Montserrat', sans-serif;
    font-size: 5rem;
    font-weight: 700;
    color: var(--hero-cream);
    margin-bottom: 1.5rem;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5);
    animation: scaleIn 0.5s ease-out 0.2s both;
}

.hero-subtitle {
    font-family: 'Montserrat', sans-serif;
    font-size: 1.5rem;
    font-weight: 500;
    color: var(--hero-linen);
    margin-bottom: 2rem;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5);
    animation: fadeIn 0.6s ease-in-out 0.4s both;
}

.hero-values {
    display: flex;
    justify-content: center;
    gap: 1.5rem;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    animation: fadeIn 0.6s ease-in-out 0.6s both;
}

.hero-value {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    background: rgba(0, 0, 0, 0.3);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(244, 163, 0, 0.3);
    border-radius: 50px;
    padding: 0.75rem 1.5rem;
    color: var(--hero-cream);
    font-family: 'Lora', serif;
    font-weight: 600;
}

.hero-value-icon {
    width: 32px;
    height: 32px;
    background: var(--saffron-gold);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    color: var(--deep-earth-brown);
}

.hero-description {
    font-family: 'Lora', serif;
    font-size: 1.1rem;
    color: var(--hero-beige);
    margin-bottom: 3rem;
    line-height: 1.8;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5);
    animation: fadeIn 0.6s ease-in-out 0.8s both;
}

.hero-cta {
    display: flex;
    gap: 1.5rem;
    justify-content: center;
    margin-bottom: 4rem;
    flex-wrap: wrap;
    animation: fadeIn 0.6s ease-in-out 1s both;
}

.scroll-indicator {
    position: absolute;
    bottom: 2rem;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    flex-direction: column;
    align-items: center;
    color: var(--hero-cream);
    cursor: pointer;
    transition: color 0.3s ease;
    animation: bounce 2s infinite;
}

.scroll-indicator:hover {
    color: var(--saffron-gold);
}

.scroll-indicator span {
    font-family: 'Lora', serif;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
    opacity: 0.8;
}

.scroll-mouse {
    width: 24px;
    height: 40px;
    border: 2px solid currentColor;
    border-radius: 12px;
    display: flex;
    justify-content: center;
    margin-bottom: 0.5rem;
    transition: border-color 0.3s ease;
}

.scroll-wheel {
    width: 4px;
    height: 12px;
    background: currentColor;
    border-radius: 2px;
    margin-top: 8px;
    animation: pulse 1.5s infinite;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.75rem 2rem;
    border: none;
    border-radius: 50px;
    font-family: 'Poppins', sans-serif;
    font-weight: 600;
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.3s ease;
    text-decoration: none;
    text-align: center;
    white-space: nowrap;
    outline: none;
    position: relative;
    overflow: hidden;
}

.btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.2);
}

.btn-primary {
    background: var(--saffron-gold);
    color: var(--deep-earth-brown);
}

.btn-primary:hover {
    background: #e69500;
    box-shadow: 0 10px 20px rgba(244, 163, 0, 0.3);
}

.btn-secondary {
    background: rgba(255, 255, 255, 0.1);
    color: white;
    border: 2px solid white;
    backdrop-filter: blur(10px);
}

.btn-secondary:hover {
    background: var(--deep-earth-brown);
    border-color: var(--deep-earth-brown);
}

.btn-outline {
    background: transparent;
    color: var(--deep-earth-brown);
    border: 2px solid var(--deep-earth-brown);
}

.btn-outline:hover {
    background: var(--deep-earth-brown);
    color: white;
}

/* Sections */
.section-header {
    text-align: center;
    margin-bottom: 4rem;
}

.section-title {
    font-family: 'Montserrat', sans-serif;
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--deep-earth-brown);
    margin-bottom: 1rem;
}

.section-subtitle {
    font-family: 'Lora', serif;
    font-size: 1.1rem;
    color: var(--gray-600);
    max-width: 600px;
    margin: 0 auto;
}

/* About Section */
.about {
    padding: 6rem 0;
    background: var(--gray-50);
}

.about-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: start;
}

.about-text h3 {
    font-family: 'Montserrat', sans-serif;
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--deep-earth-brown);
    margin-bottom: 1rem;
}

.about-text p {
    font-family: 'Lora', serif;
    color: var(--gray-700);
    margin-bottom: 2rem;
    line-height: 1.8;
}

.about-pillars {
    display: grid;
    gap: 2rem;
}

.pillar {
    display: flex;
    align-items: flex-start;
    gap: 1rem;
}

.pillar-icon {
    width: 60px;
    height: 60px;
    background: var(--saffron-gold);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--deep-earth-brown);
    font-size: 1.5rem;
    flex-shrink: 0;
}

.pillar h4 {
    font-family: 'Montserrat', sans-serif;
    font-size: 1.2rem;
    font-weight: 600;
    color: var(--deep-earth-brown);
    margin-bottom: 0.5rem;
}

.pillar p {
    font-family: 'Lora', serif;
    color: var(--gray-700);
    line-height: 1.6;
}

/* Products Section */
.products {
    padding: 6rem 0;
    background: white;
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 3rem;
}

.product-card {
    background: white;
    border-radius: 20px;
    overflow: hidden;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
    transition: all 0.3s ease;
    position: relative;
}

.product-card:hover {
    transform: translateY(-10px);
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);
}

.product-image {
    position: relative;
    height: 250px;
    background: linear-gradient(135deg, var(--saffron-gold) 0%, var(--warm-terracotta) 100%);
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.product-image-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-family: 'Montserrat', sans-serif;
    font-weight: 600;
    font-size: 1.5rem;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5);
}

.foxnut-bg {
    background: linear-gradient(135deg, var(--saffron-gold) 0%, var(--warm-terracotta) 100%);
}

.cork-bg {
    background: linear-gradient(135deg, #8B4513 0%, #A0522D 100%);
}

.product-badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background: rgba(255, 255, 255, 0.9);
    color: var(--deep-earth-brown);
    padding: 0.5rem 1rem;
    border-radius: 20px;
    font-family: 'Poppins', sans-serif;
    font-weight: 600;
    font-size: 0.9rem;
    backdrop-filter: blur(10px);
}

.product-content {
    padding: 2rem;
}

.product-content h3 {
    font-family: 'Montserrat', sans-serif;
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--deep-earth-brown);
    margin-bottom: 1rem;
}

.product-content > p {
    font-family: 'Lora', serif;
    color: var(--gray-700);
    margin-bottom: 1.5rem;
    line-height: 1.7;
}

.product-features {
    list-style: none;
    margin-bottom: 2rem;
}

.product-features li {
    position: relative;
    padding-left: 1.5rem;
    margin-bottom: 0.5rem;
    font-family: 'Lora', serif;
    color: var(--gray-700);
}

.product-features li:before {
    content: "✓";
    position: absolute;
    left: 0;
    color: var(--saffron-gold);
    font-weight: bold;
}

/* Quality Section */
.quality {
    padding: 6rem 0;
    background: var(--cream);
}

.quality-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: start;
}

.quality-text h3 {
    font-family: 'Montserrat', sans-serif;
    font-size: 1.8rem;
    font-weight: 600;
    color: var(--deep-earth-brown);
    margin-bottom: 1rem;
}

.quality-text p {
    font-family: 'Lora', serif;
    color: var(--gray-700);
    margin-bottom: 2rem;
    line-height: 1.8;
}

.quality-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
    margin-top: 2rem;
}

.stat {
    text-align: center;
}

.stat-number {
    font-family: 'Montserrat', sans-serif;
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--saffron-gold);
    margin-bottom: 0.5rem;
}

.stat-label {
    font-family: 'Lora', serif;
    color: var(--gray-700);
    font-size: 0.9rem;
}

.certifications h3 {
    font-family: 'Montserrat', sans-serif;
    font-size: 1.8rem;
    font-weight: 600;
    color: var(--deep-earth-brown);
    margin-bottom: 2rem;
}

.cert-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 1.5rem;
}

.cert-item {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: 1rem;
    background: white;
    border-radius: 15px;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
    transition: all 0.3s ease;
}

.cert-item:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
}

.cert-item i {
    color: var(--saffron-gold);
    font-size: 1.5rem;
}

.cert-item span {
    font-family: 'Poppins', sans-serif;
    font-weight: 500;
    color: var(--deep-earth-brown);
}

/* Why Us Section */
.why-us {
    padding: 6rem 0;
    background: white;
}

.why-us-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
    margin-bottom: 4rem;
}

.why-us-card {
    text-align: center;
    padding: 2rem;
    background: var(--gray-50);
    border-radius: 20px;
    transition: all 0.3s ease;
}

.why-us-card:hover {
    transform: translateY(-10px);
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);
    background: white;
}

.why-us-icon {
    width: 80px;
    height: 80px;
    background: var(--saffron-gold);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
    color: var(--deep-earth-brown);
    font-size: 2rem;
}

.why-us-card h3 {
    font-family: 'Montserrat', sans-serif;
    font-size: 1.3rem;
    font-weight: 600;
    color: var(--deep-earth-brown);
    margin-bottom: 1rem;
}

.why-us-card p {
    font-family: 'Lora', serif;
    color: var(--gray-700);
    line-height: 1.7;
}

.why-us-cta {
    text-align: center;
    padding: 3rem 2rem;
    background: var(--deep-earth-brown);
    border-radius: 20px;
    color: white;
}

.why-us-cta h3 {
    font-family: 'Montserrat', sans-serif;
    font-size: 2rem;
    font-weight: 600;
    margin-bottom: 1rem;
}

.why-us-cta p {
    font-family: 'Lora', serif;
    font-size: 1.1rem;
    margin-bottom: 2rem;
    opacity: 0.9;
}

.cta-buttons {
    display: flex;
    gap: 1rem;
    justify-content: center;
    flex-wrap: wrap;
}

.cta-buttons .btn-outline {
    border-color: white;
    color: white;
}

.cta-buttons .btn-outline:hover {
    background: white;
    color: var(--deep-earth-brown);
}

/* Testimonials Section */
.testimonials {
    padding: 6rem 0;
    background: var(--cream);
}

.testimonials-carousel {
    position: relative;
    max-width: 800px;
    margin: 0 auto 3rem;
}

.testimonial-card {
    display: none;
    background: white;
    border-radius: 20px;
    padding: 3rem;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
    text-align: center;
}

.testimonial-card.active {
    display: block;
    animation: fadeIn 0.5s ease-in-out;
}

.testimonial-rating {
    display: flex;
    justify-content: center;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
}

.testimonial-rating i {
    color: var(--saffron-gold);
    font-size: 1.2rem;
}

.testimonial-content p {
    font-family: 'Lora', serif;
    font-size: 1.2rem;
    color: var(--gray-700);
    margin-bottom: 2rem;
    line-height: 1.8;
    font-style: italic;
}

.testimonial-author {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 1rem;
}

.author-info h4 {
    font-family: 'Montserrat', sans-serif;
    font-weight: 600;
    color: var(--deep-earth-brown);
    margin-bottom: 0.25rem;
}

.author-info span {
    font-family: 'Lora', serif;
    color: var(--gray-600);
    font-size: 0.9rem;
}

.testimonial-controls {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 2rem;
}

.testimonial-prev,
.testimonial-next {
    background: var(--saffron-gold);
    color: var(--deep-earth-brown);
    border: none;
    width: 50px;
    height: 50px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.3s ease;
}

.testimonial-prev:hover,
.testimonial-next:hover {
    background: var(--deep-earth-brown);
    color: white;
    transform: scale(1.1);
}

.testimonial-dots {
    display: flex;
    gap: 0.5rem;
}

.dot {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: var(--gray-300);
    border: none;
    cursor: pointer;
    transition: all 0.3s ease;
}

.dot.active,
.dot:hover {
    background: var(--saffron-gold);
}

/* Contact Section */
.contact {
    padding: 6rem 0;
    background: white;
}

.contact-content {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.contact-form {
    display: grid;
    gap: 1.5rem;
}

.form-group {
    display: flex;
    flex-direction: column;
}

.form-group label {
    font-family: 'Poppins', sans-serif;
    font-weight: 600;
    color: var(--deep-earth-brown);
    margin-bottom: 0.5rem;
}

.form-group input,
.form-group select,
.form-group textarea {
    padding: 0.75rem 1rem;
    border: 2px solid var(--gray-300);
    border-radius: 10px;
    font-family: 'Lora', serif;
    font-size: 1rem;
    transition: all 0.3s ease;
    background: white;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
    outline: none;
    border-color: var(--saffron-gold);
    box-shadow: 0 0 0 3px rgba(244, 163, 0, 0.1);
}

.form-group textarea {
    resize: vertical;
    min-height: 120px;
}

.form-submit {
    width: 100%;
    padding: 1rem;
    margin-top: 1rem;
}

.contact-info {
    display: flex;
    flex-direction: column;
    gap: 2rem;
}

.contact-item {
    display: flex;
    align-items: flex-start;
    gap: 1rem;
}

.contact-item i {
    color: var(--saffron-gold);
    font-size: 1.5rem;
    margin-top: 0.25rem;
}

.contact-item h4 {
    font-family: 'Montserrat', sans-serif;
    font-weight: 600;
    color: var(--deep-earth-brown);
    margin-bottom: 0.5rem;
}

.contact-item p {
    font-family: 'Lora', serif;
    color: var(--gray-700);
}

.contact-cta {
    text-align: center;
    padding: 3rem 2rem;
    background: var(--slate-gray);
    border-radius: 20px;
}

.contact-cta h3 {
    font-family: 'Montserrat', sans-serif;
    font-size: 2rem;
    font-weight: 600;
    color: var(--deep-earth-brown);
    margin-bottom: 1rem;
}

.contact-cta p {
    font-family: 'Lora', serif;
    font-size: 1.1rem;
    color: var(--gray-700);
    margin-bottom: 2rem;
}

.contact-cta .btn {
    margin: 0 0.5rem;
}

/* Footer */
.footer {
    background: var(--deep-earth-brown);
    color: white;
    padding: 3rem 0 1rem;
}

.footer-content {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer-section h3 {
    font-family: 'Montserrat', sans-serif;
    font-size: 1.5rem;
    font-weight: 600;
    margin-bottom: 1rem;
    color: var(--saffron-gold);
}

.footer-section h4 {
    font-family: 'Montserrat', sans-serif;
    font-weight: 600;
    margin-bottom: 1rem;
}

.footer-section p {
    font-family: 'Lora', serif;
    margin-bottom: 1.5rem;
    opacity: 0.9;
    line-height: 1.7;
}

.footer-section ul {
    list-style: none;
}

.footer-section ul li {
    margin-bottom: 0.5rem;
}

.footer-section ul li a {
    color: white;
    text-decoration: none;
    font-family: 'Lora', serif;
    opacity: 0.9;
    transition: opacity 0.3s ease;
}

.footer-section ul li a:hover {
    opacity: 1;
    color: var(--saffron-gold);
}

.social-links {
    display: flex;
    gap: 1rem;
}

.social-links a {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    background: rgba(255, 255, 255, 0.1);
    color: white;
    border-radius: 50%;
    text-decoration: none;
    transition: all 0.3s ease;
}

.social-links a:hover {
    background: var(--saffron-gold);
    color: var(--deep-earth-brown);
    transform: translateY(-2px);
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
}

.newsletter-form input {
    flex: 1;
    padding: 0.75rem;
    border: 1px solid rgba(255, 255, 255, 0.3);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.1);
    color: white;
    font-family: 'Lora', serif;
}

.newsletter-form input::placeholder {
    color: rgba(255, 255, 255, 0.7);
}

.newsletter-form button {
    padding: 0.75rem 1.5rem;
    background: var(--saffron-gold);
    color: var(--deep-earth-brown);
    border: none;
    border-radius: 8px;
    font-family: 'Poppins', sans-serif;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
}

.newsletter-form button:hover {
    background: #e69500;
    transform: translateY(-2px);
}

.footer-bottom {
    text-align: center;
    padding-top: 2rem;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    font-family: 'Lora', serif;
    opacity: 0.8;
}

/* Animations */
@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes scaleIn {
    from {
        opacity: 0;
        transform: scale(0.9);
    }
    to {
        opacity: 1;
        transform: scale(1);
    }
}

@keyframes bounce {
    0%, 20%, 53%, 80%, 100% {
        transform: translateX(-50%) translateY(0);
    }
    40%, 43% {
        transform: translateX(-50%) translateY(-10px);
    }
    70% {
        transform: translateX(-50%) translateY(-5px);
    }
    90% {
        transform: translateX(-50%) translateY(-3px);
    }
}

@keyframes pulse {
    0%, 100% {
        opacity: 1;
    }
    50% {
        opacity: 0.5;
    }
}

/* Responsive Design */
@media (max-width: 768px) {
    .nav-menu {
        position: fixed;
        top: 70px;
        left: -100%;
        width: 100%;
        height: calc(100vh - 70px);
