(function() {
    'use strict';

    // Core Web Vitals Monitoring
    function measureCoreWebVitals() {
        // Largest Contentful Paint (LCP)
        // LCP monitoring (warnings disabled in production)
        new PerformanceObserver((list) => {
            for (const entry of list.getEntries()) {
                if (entry.startTime > 2500) {
                    // LCP performance metric logged
                }
            }
        }).observe({ entryTypes: ['largest-contentful-paint'] });

        // Interaction to Next Paint (INP) - 2025 Core Web Vital
        new PerformanceObserver((list) => {
            for (const entry of list.getEntries()) {
                if (entry.processingEnd - entry.processingStart > 200) {
                    // INP performance metric logged
                }
            }
        }).observe({ entryTypes: ['event'] });

        // Cumulative Layout Shift (CLS)
        let clsScore = 0;
        new PerformanceObserver((list) => {
            for (const entry of list.getEntries()) {
                if (!entry.hadRecentInput) {
                    clsScore += entry.value;
                    if (clsScore > 0.1) {
                        // CLS performance metric logged
                    }
                }
            }
        }).observe({ entryTypes: ['layout-shift'] });
    }

    // Structured Data Validation
    function validateStructuredData() {
